import { PageHeader } from '../components/PageHeader';
import { Button } from '../components/Button';
import { Chip, Tag } from '../components/Badge';
import { Segmented } from '../components/Segmented';

interface Lead {
  name: string;
  note: string;
  time: string;
  value: string;
  tag: 'ia' | 'ok' | 'warn' | 'neutral';
  tagLabel: string;
}

interface Column {
  title: string;
  sum: string;
  leads: Lead[];
}

const COLUMNS: Column[] = [
  {
    title: 'Novo lead', sum: 'R$ 212 mil', leads: [
      { name: 'Fernanda Melo', note: 'Perguntou valor do Corolla 2021', time: '11:52', value: '—', tag: 'ia', tagLabel: 'IA' },
      { name: 'Paulo Andrade', note: 'Tem Civic 2019 pra entrada', time: '13:15', value: 'R$ 140k', tag: 'ia', tagLabel: 'IA' },
    ],
  },
  {
    title: 'Qualificando', sum: 'R$ 186 mil', leads: [
      { name: 'Juliana Ramos', note: 'Financiamento em 48x confirmado', time: '13:48', value: 'R$ 96k', tag: 'ia', tagLabel: 'IA' },
    ],
  },
  {
    title: 'Objeção', sum: 'R$ 404 mil', leads: [
      { name: 'Marcos Pereira', note: 'Pediu 22% off — aguardando gestor', time: '14:21', value: 'R$ 404k', tag: 'warn', tagLabel: 'Escalado' },
    ],
  },
  {
    title: 'Follow-up', sum: 'R$ 118 mil', leads: [
      { name: 'Rafael Souza', note: '2 dias sem resposta — retomada amanhã', time: 'ontem', value: 'R$ 58k', tag: 'ia', tagLabel: 'IA' },
    ],
  },
  {
    title: 'Agendado', sum: 'R$ 322 mil', leads: [
      { name: 'Carlos Silva', note: 'Apresentação amanhã 14:00', time: 'amanhã', value: 'R$ 132k', tag: 'ok', tagLabel: 'Reunião' },
    ],
  },
];

/**
 * Tela: Pipeline comercial (CRM). Kanban com scroll horizontal — grid-auto-flow,
 * não flex, para colunas ficarem sempre com a mesma largura mínima (272px).
 */
export function CRM() {
  return (
    <>
      <PageHeader
        title="Pipeline comercial"
        description="Leads do WhatsApp e do simulador percorrem o mesmo funil. O agente move etapas quando identifica uma mudança real."
        actions={
          <>
            <Chip>R$ 1,24 mi em aberto</Chip>
            <Segmented options={['Kanban', 'Lista'] as const} value="Kanban" onChange={() => {}} />
            <Button variant="primary">Novo lead</Button>
          </>
        }
      />
      <div className="grid grid-flow-col auto-cols-[minmax(272px,1fr)] gap-3 overflow-x-auto pb-2">
        {COLUMNS.map((col) => (
          <div key={col.title} className="flex min-h-[520px] flex-col rounded-ds border border-line bg-bg">
            <div className="flex items-center justify-between border-b border-line px-3.5 py-3">
              <div>
                <b className="text-base font-medium text-tx">{col.title}</b>
                <span className="mt-0.5 block font-mono text-xs text-tx3">{col.sum}</span>
              </div>
              <span className="font-mono text-xs text-tx3">{col.leads.length}</span>
            </div>
            <div className="flex flex-col gap-2 p-2.5">
              {col.leads.map((lead) => (
                <div key={lead.name} className="rounded-ds border border-line bg-surface p-3 shadow-ds">
                  <div className="mb-1.5 flex items-center justify-between">
                    <b className="text-base font-medium text-tx">{lead.name}</b>
                    <Tag tone={lead.tag === 'neutral' ? undefined : lead.tag}>{lead.tagLabel}</Tag>
                  </div>
                  <p className="text-sm leading-snug text-tx2">{lead.note}</p>
                  <div className="mt-2.5 flex items-center justify-between font-mono text-xs text-tx3">
                    <span>{lead.time}</span>
                    <span className="text-tx">{lead.value}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </>
  );
}
